-- Filterable finance audit register with saved event data and live filter options.
begin;
create function charm.finance_audit_register(p_from date,p_to date,p_owner bigint default null,p_search text default '',p_activity text default '',p_status text default '',p_page integer default 1) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_rows jsonb;v_total bigint;v_activities jsonb;v_statuses jsonb;v_search text:=left(coalesce(trim(p_search),''),200);begin
 if not charm.finance_reader() then raise exception 'forbidden';end if;
 if p_from is null or p_to is null or p_to<p_from or p_to-p_from>3660 or p_page is null or p_page<0 or p_page>10000 then raise exception 'invalid';end if;
 select coalesce(jsonb_agg(x.action order by x.action),'[]') into v_activities from(select distinct l.action from charm.audit_logs l where (l.entity like 'finance_%' or l.entity='payments') and (l.entity<>'finance_requests' or charm.finance_access(l.entity_id)) and (l.created_at at time zone 'Africa/Nairobi')::date between p_from and p_to and (p_owner is null or (l.entity='finance_requests' and exists(select 1 from charm.finance_requests r where r.id=l.entity_id and r.owner_id=p_owner))))x;
 select coalesce(jsonb_agg(x.status_label order by x.status_label),'[]') into v_statuses from(select distinct coalesce(nullif(l.details->>'status',''),nullif(l.details->>'decision',''),case when l.details ? 'accepted' then l.details->>'accepted' else l.action end) status_label from charm.audit_logs l where (l.entity like 'finance_%' or l.entity='payments') and (l.entity<>'finance_requests' or charm.finance_access(l.entity_id)) and (l.created_at at time zone 'Africa/Nairobi')::date between p_from and p_to and (p_owner is null or (l.entity='finance_requests' and exists(select 1 from charm.finance_requests r where r.id=l.entity_id and r.owner_id=p_owner))))x;
 select count(*) into v_total from charm.audit_logs l join charm.users u on u.id=l.actor_id where (l.entity like 'finance_%' or l.entity='payments') and (l.entity<>'finance_requests' or charm.finance_access(l.entity_id)) and (l.created_at at time zone 'Africa/Nairobi')::date between p_from and p_to and (p_owner is null or (l.entity='finance_requests' and exists(select 1 from charm.finance_requests r where r.id=l.entity_id and r.owner_id=p_owner))) and (coalesce(p_activity,'')='' or l.action=p_activity) and (coalesce(p_status,'')='' or coalesce(nullif(l.details->>'status',''),nullif(l.details->>'decision',''),case when l.details ? 'accepted' then l.details->>'accepted' else l.action end)=p_status) and (v_search='' or concat_ws(' ',l.action,l.entity,l.entity_id::text,u.name,l.details::text) ilike '%'||v_search||'%');
 select coalesce(jsonb_agg(to_jsonb(x) order by x.id desc),'[]') into v_rows from(select l.id,l.created_at,l.actor_id,u.name actor_name,l.action,l.entity,l.entity_id,l.details,coalesce(nullif(l.details->>'status',''),nullif(l.details->>'decision',''),case when l.details ? 'accepted' then l.details->>'accepted' else l.action end) status_label from charm.audit_logs l join charm.users u on u.id=l.actor_id where (l.entity like 'finance_%' or l.entity='payments') and (l.entity<>'finance_requests' or charm.finance_access(l.entity_id)) and (l.created_at at time zone 'Africa/Nairobi')::date between p_from and p_to and (p_owner is null or (l.entity='finance_requests' and exists(select 1 from charm.finance_requests r where r.id=l.entity_id and r.owner_id=p_owner))) and (coalesce(p_activity,'')='' or l.action=p_activity) and (coalesce(p_status,'')='' or coalesce(nullif(l.details->>'status',''),nullif(l.details->>'decision',''),case when l.details ? 'accepted' then l.details->>'accepted' else l.action end)=p_status) and (v_search='' or concat_ws(' ',l.action,l.entity,l.entity_id::text,u.name,l.details::text) ilike '%'||v_search||'%') order by l.id desc limit case when p_page=0 then 1000 else 100 end offset case when p_page=0 then 0 else (p_page-1)*100 end)x;
 return jsonb_build_object('rows',v_rows,'total',v_total,'activities',v_activities,'statuses',v_statuses);
end$$;
revoke execute on function charm.finance_audit_register(date,date,bigint,text,text,text,integer) from public,anon,authenticated;
grant execute on function charm.finance_audit_register(date,date,bigint,text,text,text,integer) to authenticated;
notify pgrst, 'reload schema';
commit;
